import { FaBell, FaMoon, FaBars } from 'react-icons/fa';

const Topbar = () => {
    const user = JSON.parse(localStorage.getItem('user')) || { name: 'Admin', email: 'admin@example.com' };
    return (
        <div className="bg-white p-4 flex justify-between items-center shadow ml-[220px]">
            <div className="flex items-center gap-4">
                <img src="/logo.png" alt="Logo" className="w-8 h-8" />
                <span className="text-xl font-bold text-gray-800">ECOMMERCE</span>
                <button className="ml-4 bg-gray-100 p-2 rounded-full"><FaBars /></button>
            </div>

            <div className="flex items-center gap-4">
                <button className="bg-gray-100 p-2 rounded-full"><FaMoon /></button>
                <button className="bg-gray-100 p-2 rounded-full"><FaBell /></button>
                <div className="flex items-center gap-2">
                    <div className="bg-blue-600 text-white rounded-full w-8 h-8 flex items-center justify-center">
                        {user?.name?.[0]}
                    </div>
                    <div className="text-right">
                        <div className="font-semibold text-sm">{user?.name}</div>
                        <div className="text-xs text-gray-500">{user?.email}</div>
                    </div>
                </div>
            </div>
        </div>
    );
};
export default Topbar;
